style.css:
@-moz-document domain("roblox.com") {
/* === CHANGE THIS URL TO YOUR IMAGE === */
    :root {
        --roblox-bg-url: url("https://i.imgur.com/ZxDY4zw.jpeg"); /* <-- Replace with your image URL */
    }

    /* Outer wrappers for homepage, profile, and main content */
    body, html, .root-viewport, #container, .container-main, .content {
        background: none !important;
        background-image: var(--roblox-bg-url) !important;
        background-size: cover !important;
        background-position: center center !important;
        background-attachment: fixed !important;
    }

    /* Profile header and sections (best effort) */
    .profile-header, .profile-body, .profile-container, .profile-card, .profile-content {
        background: transparent !important;
    }

    /* Login & signup pages */
    .login-container, .signup-container, .modal-dialog {
        background: transparent !important;
    }

    /* Sections, modals, popups */
    .section, .game-card, .navbar, .footer, .modal-backdrop, .modal-content, .popup, .page-container {
        background-color: transparent !important;
    }

    /* Make popups semi-transparent so background shows */
    .modal-content, .popup {
        background-color: rgba(255, 255, 255, 0.85) !important;
        backdrop-filter: blur(3px);
    }

    /* Optional: slightly transparent top navbar */
    .navbar {
        background-color: rgba(255, 255, 255, 0.9) !important;
        backdrop-filter: blur(2px);
    }
}
